// @ts-check
import starlight from "@astrojs/starlight"
import { defineConfig } from "astro/config"

import { readRulesMarkdown } from "./src/site-content/readRulesMarkdown.ts"
import { sitePages } from "./src/site-content/sitePages.ts"

// Starlight's autogenerated sidebar needs entries backed by files, which loader pages are not
const rulePages = sitePages(await readRulesMarkdown(new URL(".", import.meta.url)))

export default defineConfig({
    site: "https://doubleloop-io.github.io",
    base: "/oxlint-plugin-effect",
    integrations: [
        starlight({
            title: "oxlint-plugin-effect",
            social: [
                {
                    icon: "github",
                    label: "GitHub",
                    href: "https://github.com/doubleloop-io/oxlint-plugin-effect",
                },
                {
                    icon: "npm",
                    label: "npm",
                    href: "https://www.npmjs.com/package/@doubleloop-io/oxlint-plugin-effect",
                },
                {
                    icon: "comment-alt",
                    label: "Issues",
                    href: "https://github.com/doubleloop-io/oxlint-plugin-effect/issues",
                },
            ],
            customCss: [
                "@fontsource-variable/inter",
                "@fontsource-variable/jetbrains-mono",
                "./src/styles/theme.css",
            ],
            sidebar: [
                {
                    label: "Rules",
                    items: Object.entries(Object.groupBy(rulePages, ({ group }) => group)).map(
                        ([group, pages = []]) => ({
                            label: group,
                            items: pages.map(({ id }) => ({ slug: id })),
                        }),
                    ),
                },
            ],
        }),
    ],
})
